import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const drnSchema = z.object({
  date: z.string().min(1, "Date is required"),
  doc_type: z.string().min(1, "Document type is required"),
  associated_project_id: z.string().optional().nullable(),
  associated_token_id: z.string().optional().nullable(),
  document_nature: z.string().min(1, "Document nature is required"),
  intended_user: z.string().min(1, "Intended user is required"),
  description: z.string().min(1, "Description is required"),
  revision: z.string().min(1, "Revision is required"),
  status: z.string().min(1, "Status is required"),
  remarks: z.string().optional().nullable(),
});

type DRNFormData = z.infer<typeof drnSchema>;

interface DRNFormProps {
  initialData?: Partial<DRNFormData>;
  onSubmit: (data: DRNFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function DRNForm({ initialData, onSubmit, onCancel, isLoading }: DRNFormProps) {
  const form = useForm<DRNFormData>({
    resolver: zodResolver(drnSchema),
    defaultValues: {
      date: initialData?.date ?? "",
      doc_type: initialData?.doc_type ?? "",
      associated_project_id: initialData?.associated_project_id ?? null,
      associated_token_id: initialData?.associated_token_id ?? null,
      document_nature: initialData?.document_nature ?? "",
      intended_user: initialData?.intended_user ?? "",
      description: initialData?.description ?? "",
      revision: initialData?.revision ?? "R0",
      status: initialData?.status ?? "draft",
      remarks: initialData?.remarks ?? null,
    },
  });

  const { data: projectsData } = useQuery({
    queryKey: ["projects-for-drn"],
    queryFn: () => api.listProjects({ page_size: 200 }),
  });

  const { data: tokensData } = useQuery({
    queryKey: ["tokens-for-drn"],
    queryFn: () => api.listTokens({ page_size: 200 }),
  });

  const projects = projectsData?.items ?? [];
  const tokens = tokensData?.items ?? [];

  const handleSubmit = async (data: DRNFormData) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await onSubmit(data as any);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Document Release Note</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="date">Date *</Label>
              <Input id="date" type="date" {...form.register("date")} />
              {form.formState.errors.date && (
                <p className="text-sm text-red-500">{form.formState.errors.date.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="doc_type">Document Type *</Label>
              <Select
                value={form.watch("doc_type")}
                onValueChange={(val) => form.setValue("doc_type", val)}
              >
                <SelectTrigger id="doc_type">
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="CON">CON</SelectItem>
                  <SelectItem value="DBR">DBR</SelectItem>
                  <SelectItem value="CAS">CAS</SelectItem>
                  <SelectItem value="GAD">GAD</SelectItem>
                  <SelectItem value="KDR">KDR</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.doc_type && (
                <p className="text-sm text-red-500">{form.formState.errors.doc_type.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Associated Project</Label>
              <Select
                value={form.watch("associated_project_id") ?? ""}
                onValueChange={(val) => form.setValue("associated_project_id", val || null)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="None" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {projects.map((p) => (
                    <SelectItem key={p.id} value={p.id}>
                      {p.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Associated Token</Label>
              <Select
                value={form.watch("associated_token_id") ?? ""}
                onValueChange={(val) => form.setValue("associated_token_id", val || null)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="None" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {tokens.map((t) => (
                    <SelectItem key={t.id} value={t.id}>
                      {t.token_id}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="document_nature">Document Nature *</Label>
              <Input id="document_nature" {...form.register("document_nature")} />
              {form.formState.errors.document_nature && (
                <p className="text-sm text-red-500">{form.formState.errors.document_nature.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="intended_user">Intended User *</Label>
              <Input id="intended_user" {...form.register("intended_user")} />
              {form.formState.errors.intended_user && (
                <p className="text-sm text-red-500">{form.formState.errors.intended_user.message as string}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description *</Label>
            <Textarea id="description" {...form.register("description")} />
            {form.formState.errors.description && (
              <p className="text-sm text-red-500">{form.formState.errors.description.message as string}</p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Revision *</Label>
              <Select
                value={form.watch("revision")}
                onValueChange={(val) => form.setValue("revision", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select revision" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="R0">R0</SelectItem>
                  <SelectItem value="R1">R1</SelectItem>
                  <SelectItem value="R2">R2</SelectItem>
                  <SelectItem value="R3">R3</SelectItem>
                  <SelectItem value="R4">R4</SelectItem>
                  <SelectItem value="R5">R5</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.revision && (
                <p className="text-sm text-red-500">{form.formState.errors.revision.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label>Status *</Label>
              <Select
                value={form.watch("status")}
                onValueChange={(val) => form.setValue("status", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="submitted">Submitted</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="rejected">Rejected</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.status && (
                <p className="text-sm text-red-500">{form.formState.errors.status.message as string}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="remarks">Remarks</Label>
            <Textarea id="remarks" {...form.register("remarks")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

