import { z } from "zod";
import { useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { api } from "@/lib/api";

const agreementSchema = z.object({
  client_id: z.string().min(1, "Client is required"),
  inquiry_id: z.string().optional(),
  service_name: z.string().min(1, "Service name is required"),
  start_date: z.string().min(1, "Start date is required"),
  end_date: z.string().optional(),
  total_tokens: z.coerce.number().nullable().optional(),
  status: z.string().min(1, "Status is required"),
  notes: z.string().optional(),
});

type AgreementFormData = z.infer<typeof agreementSchema>;

interface AgreementFormProps {
  initialData?: Partial<AgreementFormData>;
  onSubmit: (data: AgreementFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function AgreementForm({ initialData, onSubmit, onCancel, isLoading }: AgreementFormProps) {
  const form = useForm<AgreementFormData>({
    resolver: zodResolver(agreementSchema),
    defaultValues: {
      client_id: "",
      inquiry_id: "",
      service_name: "",
      start_date: new Date().toISOString().split("T")[0],
      end_date: "",
      total_tokens: null,
      status: "pending",
      notes: "",
      ...initialData,
    },
  });

  const { data: clientsData } = useQuery({
    queryKey: ["clients-list"],
    queryFn: () => api.listClients({ page: 1, page_size: 1000 }),
  });

  const { data: inquiriesData } = useQuery({
    queryKey: ["inquiries-list"],
    queryFn: () => api.listInquiries({ page: 1, page_size: 1000 }),
  });

  const clients = clientsData?.items ?? [];
  const inquiries = inquiriesData?.items ?? [];

  const handleSubmit = async (data: AgreementFormData) => {
    await onSubmit(data);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Service Agreement Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="client_id">Client *</Label>
              <Select
                value={form.watch("client_id")}
                onValueChange={(v) => form.setValue("client_id", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select client" />
                </SelectTrigger>
                <SelectContent>
                  {clients.map((client) => (
                    <SelectItem key={client.id} value={client.id}>
                      {client.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {form.formState.errors.client_id && (
                <p className="text-sm text-red-500">{form.formState.errors.client_id.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="inquiry_id">Related Inquiry (Optional)</Label>
              <Select
                value={form.watch("inquiry_id") || ""}
                onValueChange={(v) => form.setValue("inquiry_id", v || undefined)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select inquiry" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {inquiries.map((inq) => (
                    <SelectItem key={inq.id} value={inq.id}>
                      {inq.inquiry_id} - {inq.client_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="service_name">Service Name *</Label>
            <Input id="service_name" {...form.register("service_name")} />
            {form.formState.errors.service_name && (
              <p className="text-sm text-red-500">{form.formState.errors.service_name.message}</p>
            )}
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="start_date">Start Date *</Label>
              <Input id="start_date" type="date" {...form.register("start_date")} />
              {form.formState.errors.start_date && (
                <p className="text-sm text-red-500">{form.formState.errors.start_date.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="end_date">End Date</Label>
              <Input id="end_date" type="date" {...form.register("end_date")} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="total_tokens">Total Tokens</Label>
              <Input
                id="total_tokens"
                type="number"
                {...form.register("total_tokens")}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="status">Status *</Label>
              <Select
                value={form.watch("status")}
                onValueChange={(v) => form.setValue("status", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="expired">Expired</SelectItem>
                  <SelectItem value="terminated">Terminated</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.status && (
                <p className="text-sm text-red-500">{form.formState.errors.status.message}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

